    'People' => [['learners', 'Learners', 'fa-users'], ['applications', 'Applications', 'fa-inbox'], ['staff', 'Staff access', 'fa-user-shield']],
    'Learning' => [['courses', 'Courses', 'fa-book-open'], ['review', 'Course review', 'fa-clipboard-check'], ['deliverables', 'Deliverables', 'fa-folder-open'], ['certificates', 'Certificates', 'fa-certificate']],
    'Community' => [['community', 'Community', 'fa-comments'], ['market', 'Marketplace', 'fa-store'], ['alumni', 'Alumni', 'fa-user-graduate'], ['mentor', 'Mentor', 'fa-robot'], ['support', 'Support desk', 'fa-life-ring']],
    'Engagement' => [['messaging', 'Messaging', 'fa-bullhorn'], ['reminders', 'Reminders', 'fa-bell'], ['events', 'Events', 'fa-calendar-days'], ['radio', 'Radio', 'fa-radio'], ['points', 'Points and rewards', 'fa-seedling']],
