];
const ADMIN_ONLY = ['staff', 'settings', 'data', 'audit'];

function ops_page(string $title, string $html, string $sec): never {
    $nav = ''; $open = (int)val("SELECT COUNT(*) FROM support_threads WHERE COALESCE(status,'open') NOT IN ('resolved','closed')");
    foreach (OPS_NAV as $group => $items) { $nav .= '<div class="lab">' . $group . '</div>'; foreach ($items as $n) { if (in_array($n[0], ADMIN_ONLY, true) && !is_admin()) continue; $nav .= '<a class="sb ' . ($sec === $n[0] ? 'on' : '') . '" href="' . url('ops' . ($n[0] ? '/' . $n[0] : '')) . '">' . ic($n[2]) . e($n[1]) . ($n[0] === 'support' && $open ? '<span class="pill" style="margin-left:auto">' . $open . '</span>' : '') . '</a>'; } }
    $fl = ''; foreach (flash() as $f) $fl .= '<div class="flash ' . e($f[0]) . '" role="status">' . ic($f[0] === 'err' ? 'fa-circle-exclamation' : 'fa-circle-check') . '<span>' . e($f[1]) . '</span></div>';
    page($title . ' | Operations', '<div class="ops"><input type="checkbox" id="opsnav" hidden><nav class="side ops-side" aria-label="Operations menu"><a class="brand" href="' . url('ops') . '"><img src="' . asset('logo.jpg') . '" alt="WODDI logo"><span><b>Operations</b><small>WODDI Institute</small></span></a>' . $nav . '<span class="grow"></span><a class="sb" href="' . url('') . '">' . ic('fa-arrow-left') . 'Back to the app</a><a class="sb" href="' . url('logout') . '">' . ic('fa-right-from-bracket') . 'Sign out</a></nav><label class="ops-ov" for="opsnav" aria-label="Close menu"></label><div class="main"><header class="top"><label class="ib f ops-burger" for="opsnav" aria-label="Open menu">' . ic('fa-bars') . '</label><div class="ttl">' . e($title) . '</div><button class="ib" type="button" data-theme aria-label="Toggle dark mode">' . ic('fa-moon') . '</button>' . avatar(me()) . '</header><main class="cont">' . $fl . $html . '</main></div></div>', ['bare' => true]);
}
function otbl(array $heads, array $rows, string $empty = 'Nothing to show yet.'): string {
    if (!$rows) return '<div class="card"><p class="mut">' . e($empty) . '</p></div>';
    $h = '<div class="tbox"><table><thead><tr>'; foreach ($heads as $x) $h .= '<th>' . e($x) . '</th>'; $h .= '</tr></thead><tbody>';
    foreach ($rows as $r) { $h .= '<tr>'; foreach ($r as $c) $h .= '<td>' . $c . '</td>'; $h .= '</tr>'; }
    return $h . '</tbody></table></div>';
}
function kpis(array $items): string { $h = '<div class="kg">'; foreach ($items as $k) $h .= '<div class="kpi"><span class="xs mut bold" style="text-transform:uppercase;letter-spacing:.05em">' . e($k[0]) . '</span><b>' . e((string)$k[1]) . '</b>' . (!empty($k[2]) ? '<span class="xs mut">' . e($k[2]) . '</span>' : '') . '</div>'; return $h . '</div>'; }
function bars(array $data, string $color = 'var(--mag)'): string {
    $max = max(1, max($data ?: [0])); $h = '<div class="bars">';
    foreach ($data as $lab => $v) $h .= '<div title="' . e($lab . ': ' . $v) . '"><i style="height:' . max(2, (int)round($v / $max * 100)) . '%;background:' . $color . '"></i><small>' . e((string)$lab) . '</small></div>';
    return $h . '</div>';
}
function btn(string $do, string $label, array $hidden = [], string $cls = 'g', string $confirm = ''): string {
    $h = '<form method="post" style="display:inline">' . csrf_field() . '<input type="hidden" name="do" value="' . e($do) . '">'; foreach ($hidden as $k => $v) $h .= '<input type="hidden" name="' . e($k) . '" value="' . e((string)$v) . '">';
    return $h . '<button class="b ' . $cls . ' s"' . ($confirm ? ' data-confirm="' . e($confirm) . '"' : '') . '>' . $label . '</button></form>';
}
function uname(?string $u): string { static $c = []; if (!$u) return ''; if (!isset($c[$u])) { $r = row('SELECT uid, name, display_name FROM users WHERE uid = ?', [$u]); $c[$u] = $r ? '<a class="bold" href="' . url('ops/learners', ['u' => $u]) . '">' . e(display_name($r)) . '</a>' : '<span class="mut">' . e(substr($u, 0, 8)) . '</span>'; } return $c[$u]; }
function dt(?string $t): string { return $t ? '<span title="' . e($t) . ' GMT">' . e(gmdate('j M Y', strtotime($t))) . '</span>' : ''; }
function since(int $days): string { return gmdate('Y-m-d H:i:s', time() - $days * 86400); }
function oback(string $sec, array $qs = []): never { redirect('ops' . ($sec ? "/$sec" : ''), $qs); }

$sec = $seg[1] ?? ''; $do = is_post() ? (string)post('do') : ''; $id = (string)post('id');
if (in_array($sec, ADMIN_ONLY, true) && !is_admin()) { flash('That section is for admins only.', 'err'); oback(''); }

/* ───────── Overview ───────── */
if ($sec === '') {
    $total = (int)val('SELECT COUNT(*) FROM users'); $gmn = (int)val("SELECT COUNT(*) FROM users WHERE COALESCE(pathway,'gmn') <> 'nnn'");
    $a7 = (int)val('SELECT COUNT(*) FROM users WHERE last_seen > ?', [since(7)]); $a30 = (int)val('SELECT COUNT(*) FROM users WHERE last_seen > ?', [since(30)]);
    $h = kpis([['Learners', $total, "WGMN $gmn, WNNN " . ($total - $gmn)], ['Active, 7 days', $a7, ($total ? round($a7 / $total * 100) : 0) . '% of learners'], ['Active, 30 days', $a30], ['New this week', (int)val('SELECT COUNT(*) FROM users WHERE created_at > ?', [since(7)])],
        ['Certificates', (int)val('SELECT COUNT(*) FROM certificates WHERE COALESCE(revoked,0) = 0'), (int)val('SELECT COUNT(DISTINCT uid) FROM certificates WHERE COALESCE(revoked,0) = 0') . ' graduates'], ['Rooting complete', (int)val('SELECT COUNT(*) FROM user_progress WHERE rooting_completed = 1')], ['Blueprint complete', (int)val('SELECT COUNT(*) FROM user_progress WHERE blueprint_completed = 1')], ['Lessons done', (int)val("SELECT COUNT(*) FROM course_progress WHERE phase = 'lesson' AND completed = 1")],
        ['Open support', (int)val("SELECT COUNT(*) FROM support_threads WHERE COALESCE(status,'open') NOT IN ('resolved','closed')")], ['Push devices', (int)val('SELECT COUNT(*) FROM push_subscriptions'), (int)val('SELECT COUNT(DISTINCT uid) FROM push_subscriptions') . ' learners'], ['Listings', (int)val("SELECT COUNT(*) FROM mp_listings WHERE COALESCE(status,'active') <> 'removed'")], ['Community posts', (int)val("SELECT COUNT(*) FROM forum_posts WHERE COALESCE(status,'active') <> 'deleted'")]]);
    $wk = []; for ($i = 11; $i >= 0; $i--) $wk[gmdate('j M', time() - $i * 7 * 86400)] = 0;
    foreach (rows('SELECT created_at FROM users WHERE created_at > ?', [since(84)]) as $r) { $i = (int)floor((time() - strtotime((string)$r['created_at'])) / (7 * 86400)); $k = gmdate('j M', time() - $i * 7 * 86400); if (isset($wk[$k])) $wk[$k]++; }
    $dy = []; for ($i = 13; $i >= 0; $i--) $dy[gmdate('j', time() - $i * 86400)] = 0;
    foreach (rows('SELECT DATE(created_at) d, COUNT(DISTINCT uid) n FROM learning_events WHERE created_at > ? GROUP BY DATE(created_at)', [since(14)]) as $r) { $k = gmdate('j', strtotime((string)$r['d'])); if (isset($dy[$k])) $dy[$k] = (int)$r['n']; }
    $h .= '<div class="g2"><div class="card col"><h3>New learners, last 12 weeks</h3>' . bars($wk) . '</div><div class="card col"><h3>Learners active each day, last 14 days</h3>' . bars($dy, 'var(--lem)') . '</div></div>';
    $fun = [['Registered', $total], ['Started Rooting', (int)val('SELECT COUNT(*) FROM user_progress WHERE rooting_started = 1 OR rooting_completed = 1')], ['Finished Rooting', (int)val('SELECT COUNT(*) FROM user_progress WHERE rooting_completed = 1')], ['Finished Blueprint', (int)val('SELECT COUNT(*) FROM user_progress WHERE blueprint_completed = 1')], ['Started a course', (int)val('SELECT COUNT(DISTINCT uid) FROM course_progress')], ['Earned a certificate', (int)val('SELECT COUNT(DISTINCT uid) FROM certificates WHERE COALESCE(revoked,0) = 0')]];
    $h .= '<div class="g2"><div class="card col"><h3>Learner funnel</h3>'; foreach ($fun as $f) $h .= '<div class="col" style="gap:4px"><div class="row jb"><span>' . $f[0] . '</span><span class="bold">' . $f[1] . ' <span class="mut xs">' . ($total ? round($f[1] / $total * 100) : 0) . '%</span></span></div>' . bar($total ? (int)round($f[1] / $total * 100) : 0) . '</div>';
    $h .= '</div><div class="card col"><h3>Top countries</h3>'; foreach (rows("SELECT COALESCE(NULLIF(country,''),'Not set') c, COUNT(*) n FROM users GROUP BY c ORDER BY n DESC LIMIT 8") as $r) $h .= '<div class="row jb"><span>' . e($r['c']) . '</span><span class="bold">' . (int)$r['n'] . '</span></div>'; $h .= '</div></div>';
    $top = []; foreach (rows("SELECT course_id, COUNT(DISTINCT uid) n, SUM(phase = 'lesson' AND completed = 1) l FROM course_progress GROUP BY course_id ORDER BY n DESC LIMIT 8") as $r) { $it = catalog_item((string)$r['course_id']); $top[] = [e($it['title'] ?? $r['course_id']), (int)$r['n'], (int)$r['l']]; }
    $recent = []; foreach (rows('SELECT uid, kind, ref, created_at FROM learning_events ORDER BY created_at DESC LIMIT 10') as $r) $recent[] = [uname($r['uid']), e(str_replace('_', ' ', (string)$r['kind'])), e((string)$r['ref']), ago($r['created_at'])];
    $h .= '<div class="g2"><div class="col"><h3>Most taken courses</h3>' . otbl(['Course', 'Learners', 'Lessons done'], $top) . '</div><div class="col"><h3>Latest learning activity</h3>' . otbl(['Learner', 'Event', 'Detail', 'When'], $recent) . '</div></div>';
    ops_page('Overview', '<div class="col" style="gap:18px">' . $h . '</div>', $sec);
}

/* ───────── Learners ───────── */
if ($sec === 'learners') {
    if ($do) {
        $t = (string)post('uid'); $u = row('SELECT * FROM users WHERE uid = ?', [$t]); if (!$u) oback('learners');
        if ($do === 'network') { upd('users', ['pathway' => post('pathway') === 'nnn' ? 'nnn' : 'gmn', 'updated_at' => now()], 'uid = ?', [$t]); audit('network_change', $t, null, ['to' => post('pathway')]); flash('Network changed.'); }
        if ($do === 'status') { upd('users', ['status' => post('status') === 'suspended' ? 'suspended' : 'active', 'ban_reason' => post('reason')], 'uid = ?', [$t]); audit('status_change', $t, null, ['to' => post('status')]); flash('Account status updated.'); }
        if ($do === 'role' && is_admin()) { $r = in_array(post('role'), ['student', 'tutor', 'instructor', 'moderator', 'admin', 'super_admin'], true) ? post('role') : 'student'; if ($t === $uid && !in_array($r, ['admin', 'super_admin'], true)) flash('You cannot remove your own admin role.', 'err'); else { upd('users', ['role' => $r], 'uid = ?', [$t]); audit('role_change', $t, null, ['to' => $r]); flash('Role updated.'); } }
        if ($do === 'points') { $n = (int)post('points'); if ($n) { award($t, $n, 'admin:' . mb_substr((string)post('reason', 'adjustment'), 0, 60) . ':' . time()); unset($_SESSION['cheer']); audit('points_adjust', $t, null, ['points' => $n]); flash('Points adjusted.'); } }
        if ($do === 'message') { notify($t, (string)post('title', 'A message from WODDI'), (string)post('body'), 'messages', 'admin'); if (post('email') && filter_var($u['email'], FILTER_VALIDATE_EMAIL)) send_mail($u['email'], (string)post('title', 'A message from WODDI'), mail_html((string)post('title'), (string)post('body'), 'messages')); audit('direct_message', $t); flash('Message sent in the app and by push.'); }
        if ($do === 'reset') { $tok = bin2hex(random_bytes(32)); q('REPLACE INTO password_resets (token, uid, expires_at) VALUES (?,?,?)', [hash('sha256', $tok), $t, gmdate('Y-m-d H:i:s', time() + 86400)]); audit('reset_link', $t); flash('Reset link, valid for 24 hours. Copy and send it to the learner: ' . url('reset', ['t' => $tok])); }
        if ($do === 'unlock') { save_journey($t, ['course_hub_unlocked' => 1]); audit('hub_unlock', $t); flash('Course Hub unlocked for this learner.'); }
        oback('learners', ['u' => $t]);
    }
    if ($t = (string)($_GET['u'] ?? '')) {
        $u = row('SELECT * FROM users WHERE uid = ?', [$t]); if (!$u) oback('learners');
        $j = journey($t); $pts = points($t); $nn = ($u['pathway'] ?? '') === 'nnn';
        $h = '<a class="b g s" style="align-self:flex-start" href="' . url('ops/learners') . '">' . ic('fa-arrow-left') . ' All learners</a><div class="card row wrap">' . avatar($u, 'big') . '<div class="grow" style="min-width:200px"><h2>' . e(display_name($u)) . '</h2><p class="mut sm">' . e($u['email']) . ($u['phone'] ? ', ' . e($u['phone']) : '') . '</p><p class="mut sm">' . e(implode(', ', array_filter([$u['city'], $u['state'], $u['country']]))) . '</p><div class="row wrap" style="gap:6px;margin-top:6px">' . pill($nn ? 'WNNN' : 'WGMN') . pill(ucfirst((string)($u['role'] ?: 'student')), 'n') . pill(ucfirst((string)($u['status'] ?: 'active')), ($u['status'] ?: 'active') === 'active' ? 'l' : 'g') . '</div></div><div class="col" style="gap:2px;text-align:right"><span class="xs mut">Joined ' . dt($u['created_at']) . '</span><span class="xs mut">Last seen ' . ($u['last_seen'] ? ago($u['last_seen']) : 'never') . '</span></div></div>'
            . kpis([['Growth Points', $pts, level_for($pts)], ['Rooting', count($j['rooting']) . ' / ' . $j['root_total']], ['Blueprint', $j['blue_n'] . ' / ' . $j['blue_total']], ['Certificates', (int)val('SELECT COUNT(*) FROM certificates WHERE uid = ? AND COALESCE(revoked,0) = 0', [$t])]]);
        $cp = []; foreach (rows("SELECT course_id, SUM(phase = 'lesson' AND completed = 1) l, SUM(phase = 'module-quiz' AND completed = 1) qz, MAX(final_quiz_passed) f, MAX(updated_at) u FROM course_progress WHERE uid = ? GROUP BY course_id ORDER BY u DESC", [$t]) as $r) { $it = catalog_item((string)$r['course_id']); $cp[] = [e($it['title'] ?? $r['course_id']), (int)$r['l'] . ($it ? ' / ' . $it['lessons'] : ''), (int)$r['qz'], $r['f'] ? pill('Passed', 'l') : '', dt($r['u'])]; }
        $h .= '<h3>Courses</h3>' . otbl(['Course', 'Lessons', 'Quizzes passed', 'Final', 'Last activity'], $cp, 'No course started yet.');
        $h .= '<div class="g2"><form method="post" class="card col">' . csrf_field() . '<input type="hidden" name="do" value="message"><input type="hidden" name="uid" value="' . e($t) . '"><h3>Send a message</h3><input class="inp" name="title" required placeholder="Title"><textarea class="inp" name="body" rows="3" required placeholder="Message"></textarea><label class="row"><input type="checkbox" name="email" value="1"> Also send by email</label><button class="b s" style="align-self:flex-start">' . ic('fa-paper-plane') . ' Send</button></form><div class="card col"><h3>Account actions</h3>'
            . '<form method="post" class="row">' . csrf_field() . '<input type="hidden" name="do" value="network"><input type="hidden" name="uid" value="' . e($t) . '"><select class="inp" name="pathway"><option value="gmn"' . ($nn ? '' : ' selected') . '>WGMN</option><option value="nnn"' . ($nn ? ' selected' : '') . '>WNNN</option></select><button class="b g s">Change network</button></form>'
            . (is_admin() ? '<form method="post" class="row">' . csrf_field() . '<input type="hidden" name="do" value="role"><input type="hidden" name="uid" value="' . e($t) . '"><select class="inp" name="role">' . implode('', array_map(fn($r) => '<option' . (($u['role'] ?: 'student') === $r ? ' selected' : '') . '>' . $r . '</option>', ['student', 'tutor', 'instructor', 'moderator', 'admin', 'super_admin'])) . '</select><button class="b g s">Set role</button></form>' : '')
            . '<form method="post" class="row">' . csrf_field() . '<input type="hidden" name="do" value="points"><input type="hidden" name="uid" value="' . e($t) . '"><input class="inp" type="number" name="points" placeholder="+50 or -20" required style="max-width:130px"><input class="inp" name="reason" placeholder="Reason"><button class="b g s">Adjust points</button></form><div class="row wrap">' . btn('reset', ic('fa-key') . ' Password reset link', ['uid' => $t]) . btn('unlock', ic('fa-lock-open') . ' Unlock Course Hub', ['uid' => $t]) . btn('status', ($u['status'] ?: 'active') === 'suspended' ? 'Reactivate account' : 'Suspend account', ['uid' => $t, 'status' => ($u['status'] ?: 'active') === 'suspended' ? 'active' : 'suspended'], 'g', 'Change this account status?') . '</div></div></div>';
        $tx = []; foreach (rows('SELECT * FROM growth_transactions WHERE uid = ? ORDER BY created_at DESC LIMIT 15', [$t]) as $r) $tx[] = [e($r['reason']), (int)$r['points'], dt($r['created_at'])];
        $h .= '<h3>Latest points</h3>' . otbl(['Reason', 'Points', 'Date'], $tx);
        ops_page(display_name($u), '<div class="col" style="gap:16px">' . $h . '</div>', $sec);
    }
    $qs = trim((string)($_GET['q'] ?? '')); $nf = (string)($_GET['net'] ?? ''); $cf = (string)($_GET['country'] ?? ''); $af = (string)($_GET['act'] ?? ''); $pg = max(1, (int)($_GET['p'] ?? 1)); $w = '1=1'; $p = [];
    if ($qs !== '') { $w .= ' AND (name LIKE ? OR display_name LIKE ? OR email LIKE ? OR phone LIKE ?)'; array_push($p, "%$qs%", "%$qs%", "%$qs%", "%$qs%"); }
    if ($nf === 'nnn') $w .= " AND pathway = 'nnn'"; elseif ($nf === 'gmn') $w .= " AND COALESCE(pathway,'gmn') <> 'nnn'";
    if ($cf) { $w .= ' AND country = ?'; $p[] = $cf; }
    if ($af === 'active') { $w .= ' AND last_seen > ?'; $p[] = since(7); } elseif ($af === 'quiet') { $w .= ' AND (last_seen IS NULL OR last_seen < ?)'; $p[] = since(14); }
    $n = (int)val("SELECT COUNT(*) FROM users WHERE $w", $p);
    if (isset($_GET['csv'])) csv_out('learners', rows("SELECT uid, COALESCE(NULLIF(display_name,''), name) name, email, phone, pathway, role, country, state, city, profession, status, created_at, last_seen FROM users WHERE $w ORDER BY created_at DESC", $p));
    $list = rows("SELECT * FROM users WHERE $w ORDER BY created_at DESC LIMIT 50 OFFSET " . (($pg - 1) * 50), $p); $r2 = [];
    foreach ($list as $u) $r2[] = ['<a class="row" href="' . url('ops/learners', ['u' => $u['uid']]) . '">' . avatar($u, 's') . '<span><span class="bold" style="display:block">' . e(display_name($u)) . '</span><span class="mut xs">' . e($u['email']) . '</span></span></a>', pill(($u['pathway'] ?? '') === 'nnn' ? 'WNNN' : 'WGMN', 'n'), e($u['country']), e(ucfirst((string)($u['role'] ?: 'student'))), dt($u['created_at']), $u['last_seen'] ? ago($u['last_seen']) : '<span class="mut">never</span>'];
    $sel = fn($n1, $opts, $cur) => '<select class="inp" name="' . $n1 . '" style="width:auto">' . implode('', array_map(fn($k, $v) => '<option value="' . e($k) . '"' . ((string)$k === $cur ? ' selected' : '') . '>' . e($v) . '</option>', array_keys($opts), $opts)) . '</select>';
    $countries = ['' => 'All countries']; foreach (rows("SELECT DISTINCT country FROM users WHERE country IS NOT NULL AND country <> '' ORDER BY country") as $c) $countries[$c['country']] = $c['country'];
    $keep = array_filter(['q' => $qs, 'net' => $nf, 'country' => $cf, 'act' => $af]);
    $h = '<form method="get" class="row wrap"><input class="inp grow" style="min-width:200px" type="search" name="q" value="' . e($qs) . '" placeholder="Search name, email or phone">' . $sel('net', ['' => 'Both networks', 'gmn' => 'WGMN', 'nnn' => 'WNNN'], $nf) . $sel('country', $countries, $cf) . $sel('act', ['' => 'Any activity', 'active' => 'Active this week', 'quiet' => 'Quiet 14 days or more'], $af) . '<button class="b s">Filter</button><a class="b g s" href="' . url('ops/learners', $keep + ['csv' => 1]) . '">' . ic('fa-file-csv') . ' Export</a></form><p class="mut sm">' . $n . ' learners match.</p>' . otbl(['Learner', 'Network', 'Country', 'Role', 'Joined', 'Last seen'], $r2)
        . '<div class="row jb">' . ($pg > 1 ? '<a class="b g s" href="' . url('ops/learners', $keep + ['p' => $pg - 1]) . '">Previous</a>' : '<span></span>') . '<span class="mut sm">Page ' . $pg . ' of ' . max(1, (int)ceil($n / 50)) . '</span>' . ($pg * 50 < $n ? '<a class="b g s" href="' . url('ops/learners', $keep + ['p' => $pg + 1]) . '">Next</a>' : '<span></span>') . '</div>';
    ops_page('Learners', '<div class="col" style="gap:14px">' . $h . '</div>', $sec);
}

/* ───────── Student success ───────── */
if ($sec === 'success') {
    if ($do === 'nudge') { $ids = array_slice(array_filter((array)($_POST['uids'] ?? [])), 0, 300); if ($ids) { campaign_queue((string)post('title', 'We miss you at WODDI Institute'), (string)post('body'), ['inapp', 'push', 'email'], $ids, 'learn', 'student success'); $r = campaign_run(15); audit('nudge', null, null, ['count' => count($ids)]); flash(count($ids) . ' learners nudged in the app. Email and push: ' . ($r['email'] + $r['push']) . ' sent, ' . $r['left'] . ' still sending in the background.'); } oback('success', ['band' => $_GET['band'] ?? '14']); }
    if ($do === 'case') { q('REPLACE INTO retention_cases (uid, owner_name, reason_code, next_action, next_action_due, recovery_status, updated_by, updated_at) VALUES (?,?,?,?,?,?,?,?)', [post('uid'), display_name($me), post('reason'), post('next'), post('due') ?: null, post('status', 'open'), $uid, now()]); flash('Follow-up saved.'); oback('success', ['band' => $_GET['band'] ?? '14']); }
    $band = (string)($_GET['band'] ?? '14'); $bands = ['7' => [7, 14, 'Slipping, 7 to 13 days'], '14' => [14, 30, 'At risk, 14 to 29 days'], '30' => [30, 3650, 'Lost touch, 30 days or more'], 'never' => [0, 0, 'Registered, never started']];
    $cnt = fn($a, $b) => (int)val("SELECT COUNT(*) FROM users WHERE COALESCE(role,'student') NOT IN ('admin','super_admin') AND last_seen < ? AND last_seen >= ?", [since($a), since($b)]);
