    if ($do === 'test') { require_once APP_ROOT . '/lib/push.php'; $n = push_to_user($uid, 'WODDI Institute test', 'Push notifications are working on this device.', url('ops/push')); flash($n ? "Test push sent to $n of your devices." : 'No push went out. Turn on notifications on this device first (button below), then test again.', $n ? 'ok' : 'err'); oback('push'); }
    $r2 = []; foreach (rows("SELECT SUBSTRING_INDEX(SUBSTRING_INDEX(endpoint, '/', 3), '/', -1) host, COUNT(*) n, COUNT(DISTINCT uid) u FROM push_subscriptions GROUP BY host ORDER BY n DESC") as $r) $r2[] = [e($r['host']), (int)$r['n'], (int)$r['u']];
    ops_page('Push notifications', '<div class="col" style="gap:14px;max-width:900px">' . kpis([['Devices', (int)val('SELECT COUNT(*) FROM push_subscriptions')], ['Learners reachable', (int)val('SELECT COUNT(DISTINCT uid) FROM push_subscriptions')], ['My devices', (int)val('SELECT COUNT(*) FROM push_subscriptions WHERE uid = ?', [$uid])], ['Keys', cfg('vapid.public') ? 'Set' : 'Missing']]) . '<div class="card col"><h3>Test on this device</h3><p class="mut sm">First allow notifications on this phone or computer, then send yourself a test.</p><div class="row wrap"><button class="b g s" type="button" data-push>' . ic('fa-bell') . ' Turn on notifications here</button>' . btn('test', ic('fa-paper-plane') . ' Send me a test push', [], '') . '</div></div><div class="card col"><h3>Public key</h3><input class="inp" readonly onclick="this.select()" value="' . e((string)cfg('vapid.public', '')) . '"><p class="mut sm">Devices are tied to this key. If the key ever changes, every learner has to allow notifications again, so keep config.php safe.</p></div><h3>Devices by push service</h3>' . otbl(['Service', 'Devices', 'Learners'], $r2, 'No device has turned notifications on yet.') . '</div>', $sec);
}

/* ───────── Audit ───────── */
if ($sec === 'audit') {
    $r2 = []; foreach (rows('SELECT * FROM admin_audit_logs ORDER BY created_at DESC LIMIT 200') as $a) $r2[] = [uname($a['admin_uid']), e(str_replace('_', ' ', (string)$a['action'])), uname($a['target_uid']) ?: e((string)$a['target_id']), '<span class="xs mut">' . e(mb_strimwidth((string)$a['meta'], 0, 120, '...')) . '</span>', ago($a['created_at'])];
    ops_page('Audit log', '<div class="col" style="gap:14px"><p class="mut">Every admin action in Operations is written here.</p>' . otbl(['Staff', 'Action', 'Target', 'Detail', 'When'], $r2) . '</div>', $sec);
}

/* ───────── Data browser ───────── */
if ($sec === 'data') {
    $S = schema(); $t = (string)($seg[2] ?? ''); $hide = ['auth_accounts', 'password_resets'];
    if ($t === '' || !isset($S[$t]) || in_array($t, $hide, true)) {
        $r2 = []; foreach ($S as $name => $d) { if (in_array($name, $hide, true)) continue; try { $n = (int)val("SELECT COUNT(*) FROM `$name`"); } catch (Throwable $e) { $n = 0; } $r2[] = ['<a class="bold" href="' . url("ops/data/$name") . '">' . e($name) . '</a>', $n, count($d['cols'])]; }
        ops_page('Data browser', '<div class="col" style="gap:14px"><p class="mut">Every table that came across from Supabase. Open one to search, edit, delete or export its rows. Take care: changes here are immediate.</p>' . otbl(['Table', 'Rows', 'Columns'], $r2) . '</div>', $sec);
    }
    $cols = array_keys($S[$t]['cols']); $pk = $S[$t]['pk']; $where = implode(' AND ', array_map(fn($k) => "`$k` = ?", $pk)); $key = fn($r) => base64_encode(json_encode(array_map(fn($k) => $r[$k], $pk)));
    $pkv = fn(string $k) => (array)json_decode((string)base64_decode($k), true);
    if ($do === 'row-save') { $d = []; foreach ($cols as $c) if (isset($_POST['f'][$c]) && !in_array($c, $pk, true)) $d[$c] = $_POST['f'][$c] === '' && !empty($_POST['null'][$c]) ? null : $_POST['f'][$c]; if ($d) { upd($t, $d, $where, $pkv((string)post('k'))); audit('data_edit', null, (string)post('k'), [], $t); flash('Row saved.'); } oback("data/$t"); }
    if ($do === 'row-del') { q("DELETE FROM `$t` WHERE $where", $pkv((string)post('k'))); audit('data_delete', null, (string)post('k'), [], $t); flash('Row deleted.'); oback("data/$t"); }
    if ($do === 'row-add') { $d = []; foreach ($cols as $c) if (isset($_POST['f'][$c]) && $_POST['f'][$c] !== '') $d[$c] = $_POST['f'][$c]; ins($t, $d); audit('data_add', null, null, [], $t); flash('Row added.'); oback("data/$t"); }
    if (isset($_GET['csv'])) { audit('export', null, $t); csv_out($t, rows("SELECT * FROM `$t` LIMIT 50000")); }
    if (($k = (string)($_GET['edit'] ?? '')) !== '' || isset($_GET['add'])) {
        $r = $k !== '' ? row("SELECT * FROM `$t` WHERE $where", $pkv($k)) : array_fill_keys($cols, ''); if (!$r) oback("data/$t");
        $h = '<a class="b g s" style="align-self:flex-start" href="' . url("ops/data/$t") . '">' . ic('fa-arrow-left') . ' Back to ' . e($t) . '</a><form method="post" class="card col">' . csrf_field() . '<input type="hidden" name="do" value="' . ($k !== '' ? 'row-save' : 'row-add') . '"><input type="hidden" name="k" value="' . e($k) . '">';
        foreach ($cols as $c) { $v = (string)($r[$c] ?? ''); $ro = $k !== '' && in_array($c, $pk, true); $h .= '<label class="fld">' . e($c) . ' <small class="mut">' . e($S[$t]['cols'][$c]['k'] ?? '') . '</small>' . (strlen($v) > 90 || str_contains($v, "\n") ? '<textarea class="inp" rows="4" name="f[' . e($c) . ']"' . ($ro ? ' readonly' : '') . '>' . e($v) . '</textarea>' : '<input class="inp" name="f[' . e($c) . ']" value="' . e($v) . '"' . ($ro ? ' readonly' : '') . '>') . ($k !== '' && !$ro ? '<small><label><input type="checkbox" name="null[' . e($c) . ']" value="1"' . ($r[$c] === null ? ' checked' : '') . '> empty means no value</label></small>' : '') . '</label>'; }
        ops_page($t, '<div class="col" style="gap:14px;max-width:820px">' . $h . '<button class="b" style="align-self:flex-start">' . ic('fa-check') . ' Save row</button></form></div>', $sec);
    }
    $qs = trim((string)($_GET['q'] ?? '')); $pg = max(1, (int)($_GET['p'] ?? 1)); $w = '1=1'; $p = [];
    if ($qs !== '') { $w = '(' . implode(' OR ', array_map(fn($c) => "CAST(`$c` AS CHAR) LIKE ?", $cols)) . ')'; $p = array_fill(0, count($cols), "%$qs%"); }
    $n = (int)val("SELECT COUNT(*) FROM `$t` WHERE $w", $p); $order = in_array('created_at', $cols, true) ? 'ORDER BY created_at DESC' : ''; $show = array_slice($cols, 0, 7); $r2 = [];
    foreach (rows("SELECT * FROM `$t` WHERE $w $order LIMIT 40 OFFSET " . (($pg - 1) * 40), $p) as $r) { $cells = array_map(fn($c) => '<span class="sm">' . e(mb_strimwidth((string)($r[$c] ?? ''), 0, 60, '...')) . '</span>', $show); $cells[] = '<span class="row" style="gap:6px"><a class="b g s" href="' . url("ops/data/$t", ['edit' => $key($r)]) . '">' . ic('fa-pen') . '</a>' . btn('row-del', ic('fa-trash'), ['k' => $key($r)], 'g', 'Delete this row for good?') . '</span>'; $r2[] = $cells; }
    ops_page($t, '<div class="col" style="gap:14px"><div class="row wrap"><a class="b g s" href="' . url('ops/data') . '">' . ic('fa-arrow-left') . ' Tables</a><form method="get" class="row grow"><input class="inp" type="search" name="q" value="' . e($qs) . '" placeholder="Search every column"><button class="b s">Search</button></form><a class="b g s" href="' . url("ops/data/$t", ['add' => 1]) . '">' . ic('fa-plus') . ' Add row</a><a class="b g s" href="' . url("ops/data/$t", ['csv' => 1]) . '">' . ic('fa-file-csv') . ' Export</a></div><p class="mut sm">' . $n . ' rows. Showing the first ' . count($show) . ' of ' . count($cols) . ' columns. Open a row to see them all.</p>' . otbl(array_merge($show, ['']), $r2) . '<div class="row jb">' . ($pg > 1 ? '<a class="b g s" href="' . url("ops/data/$t", ['q' => $qs, 'p' => $pg - 1]) . '">Previous</a>' : '<span></span>') . '<span class="mut sm">Page ' . $pg . ' of ' . max(1, (int)ceil($n / 40)) . '</span>' . ($pg * 40 < $n ? '<a class="b g s" href="' . url("ops/data/$t", ['q' => $qs, 'p' => $pg + 1]) . '">Next</a>' : '<span></span>') . '</div></div>', $sec);
}
oback('');
